<style>
:root{color-scheme:dark;--bg:#070a12;--panel:#0b1220;--panel2:#101d31;--line:#203653;--blue:#1677ff;--bright:#42a5ff;--text:#f4f8ff;--muted:#91a5c2}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 70% -10%,#112b53 0,transparent 36rem),var(--bg);color:var(--text);font:14px/1.5 Inter,"Segoe UI",Arial,sans-serif}a{color:inherit;text-decoration:none}button,input{font:inherit}.topbar{height:76px;border-bottom:1px solid #17416e;background:#050b16eF;display:flex;align-items:center;gap:28px;padding:0 28px;position:sticky;top:0;z-index:5}.brand{font-size:29px;font-weight:950;letter-spacing:-1.5px;white-space:nowrap}.brand span{color:var(--blue)}.search{max-width:530px;flex:1;border:1px solid #23456f;border-radius:99px;padding:12px 18px;background:#081326;color:#8ba7ce}.toplinks{margin-left:auto;display:flex;gap:18px;align-items:center;color:#8ebaff}.layout{display:grid;grid-template-columns:230px minmax(290px,390px) minmax(0,1fr);gap:0;max-width:1700px;margin:18px auto;padding:0 14px;min-height:calc(100vh - 110px)}.sidebar{padding:12px 12px 20px 0;border-right:1px solid var(--line);display:flex;flex-direction:column;gap:7px}.navlink{padding:12px 14px;border-radius:8px;color:#9bb4d8;font-weight:650;display:flex;align-items:center;gap:12px}.navlink:hover,.navlink.active{background:linear-gradient(90deg,#103d80,#0a1d3a);color:white;box-shadow:inset 3px 0 var(--blue)}.navicon{width:22px;text-align:center;color:#65aaff;font-size:18px}.promo{margin-top:auto;padding:18px;border:1px solid #1c477a;border-radius:12px;background:linear-gradient(180deg,rgba(5,12,24,.18) 0%,rgba(5,12,24,.94) 65%),url('https://images.pexels.com/photos/15208152/pexels-photo-15208152.jpeg?auto=compress&cs=tinysrgb&w=900') center/cover no-repeat,#080f1c;overflow:hidden;min-height:245px;display:flex;flex-direction:column;justify-content:flex-end;box-shadow:0 14px 35px #0005}.promo b{font-size:24px;line-height:1.1;display:block;letter-spacing:-.7px}.promo span{color:var(--bright)}.promo p{color:#91a9cb;font-size:12px}.inbox{border:1px solid var(--line);border-radius:13px 0 0 13px;overflow:hidden;background:#08101d}.inboxhead{padding:22px 22px 16px;border-bottom:1px solid #172d49}.heading{display:flex;align-items:center;justify-content:space-between;font-size:23px;font-weight:850;letter-spacing:-.5px}.count{background:var(--blue);border-radius:20px;padding:2px 9px;font-size:12px;margin-left:6px}.filter{margin-top:16px;width:100%;border:1px solid #24466f;border-radius:99px;padding:11px 15px;background:#071327;color:var(--text);outline:none}.conversations{padding:8px 12px}.item{display:flex;align-items:center;gap:12px;padding:13px 10px;border-bottom:1px solid #152741;transition:.2s}.item:hover,.item.unread{background:linear-gradient(100deg,#0d2b59,#0a1525);border-radius:8px}.avatar{width:44px;height:44px;flex:none;border-radius:50%;display:grid;place-items:center;border:1px solid #3277c0;background:linear-gradient(145deg,#163e6b,#10192b);color:#d5eaff;font-weight:850;font-size:17px}.details{min-width:0;flex:1}.name{font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.preview{font-size:12px;color:#8fa8cc;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:3px}.meta{font-size:11px;color:#7693ba;text-align:right}.unread .name{color:#fff}.unread .preview{color:#c8dcfa}.badge{display:inline-block;margin-top:5px;background:var(--blue);border-radius:20px;min-width:20px;padding:1px 6px;text-align:center;color:white;font-size:11px}.emptychat{border:1px solid var(--line);border-left:0;border-radius:0 13px 13px 0;display:flex;align-items:center;justify-content:center;text-align:center;padding:35px;background:linear-gradient(90deg,rgba(5,10,19,.97) 0%,rgba(5,10,19,.82) 46%,rgba(5,10,19,.36) 100%),url('https://images.pexels.com/photos/7211301/pexels-photo-7211301.jpeg?auto=compress&cs=tinysrgb&w=1600') center/cover no-repeat,#080f1c;position:relative}.emptybox{max-width:370px}.bubbleicon{width:76px;height:76px;border:1px solid #245b96;border-radius:23px;display:grid;place-items:center;margin:0 auto 22px;background:#0d2240;color:#56a7ff;font-size:31px;box-shadow:0 0 50px #1677ff18}.emptybox h2{font-size:26px;margin:0 0 8px;letter-spacing:-.7px}.emptybox p{color:var(--muted);margin:0 0 20px}.primary{display:inline-flex;background:linear-gradient(120deg,#1677ff,#0754ca);border-radius:8px;padding:11px 16px;font-weight:800;box-shadow:0 7px 22px #1677ff30}.flash{margin:12px;padding:12px;border:1px solid #1f765d;background:#0d2b25;color:#8cf0cb;border-radius:8px}
@media(max-width:1050px){.layout{grid-template-columns:72px minmax(270px,360px) minmax(0,1fr)}.sidebar{align-items:center}.navlink{justify-content:center;width:48px;padding:12px}.navlabel,.promo{display:none}.topbar{padding:0 18px}.search{display:none}}
